"""Seed the reviewed Patching inactive operator label as an immutable policy."""

from __future__ import annotations

import base64
import hashlib
import json
import zlib
from typing import ClassVar

from django.db import migrations


NEW_VERSION = "conditions-taxonomy-5"
POLICY_DIGEST = "4e5266006df23717fe3a7971d103d070fb71f62d2700733598e20010224faf41"
POLICY_PAYLOAD = ""


def seed_policy(apps, schema_editor):
    policy = json.loads(zlib.decompress(base64.b64decode(POLICY_PAYLOAD)))
    digest = hashlib.sha256(json.dumps(policy, sort_keys=True).encode()).hexdigest()
    if digest != POLICY_DIGEST or policy["version"] != NEW_VERSION:
        raise RuntimeError("Embedded policy payload does not match its declared digest")
    with schema_editor.connection.cursor() as cursor:
        cursor.execute(
            "SELECT operations.create_condition_policy_version(%s, %s, %s::jsonb)",
            (NEW_VERSION, digest, json.dumps(policy)),
        )


class Migration(migrations.Migration):
    dependencies: ClassVar[list[tuple[str, str]]] = [("operations", "0176_harden_entity_link_history_window")]
    operations: ClassVar[list] = [migrations.RunPython(seed_policy, migrations.RunPython.noop)]
